"""Panduan membaca data, hasil klasterisasi, dan fitur aplikasi."""

import streamlit as st

from firewatch.ui import page_header

page_header("Pertanyaan yang sering diajukan", "Panduan singkat untuk memahami data, klaster, dan interpretasi kerawanan.", "FAQ")

questions = [
    ("Apa tujuan Jakarta Siaga?", "Jakarta Siaga membantu mengelompokkan kelurahan DKI Jakarta berdasarkan kemiripan sembilan indikator kondisi kelistrikan dan gas. Hasilnya mendukung pemahaman pola wilayah dan penyusunan prioritas mitigasi berbasis data."),
    ("Bagaimana cara mulai menggunakan aplikasi?", "Buka Beranda untuk ringkasan wilayah. Di Dataset, telusuri 2425.csv atau unggah CSV sesuai format. Buka Klasterisasi untuk melihat peta, hasil tiap kelurahan, profil klaster, dan evaluasi. Dataset bawaan langsung dapat digunakan tanpa mengunggah file."),
    ("Mengapa 534 baris data menjadi 267 kelurahan?", "Data bawaan memiliki satu observasi tiap kelurahan pada 2024 dan 2025. Sistem menghitung Z-score setiap indikator secara terpisah untuk 2024 dan 2025, lalu merata-ratakan Z-score antarperiode berdasarkan kota, kecamatan, dan kelurahan. Dengan demikian, setiap kelurahan memperoleh satu hasil klaster."),
    ("Apa arti klaster dan nomor klaster?", "Klaster adalah kelompok kelurahan dengan pola sembilan indikator yang mirip. Nomornya adalah penanda kelompok pada satu algoritma. Nomor diurutkan dari rata-rata centroid indikator tertinggi agar mudah dibaca. Nomor klaster antaralgoritma tidak menunjukkan kelompok yang sama dan tidak menyatakan probabilitas kebakaran."),
    ("Bagaimana membaca sebaran klaster dan profil?", "Klasterisasi menampilkan satu diagram terpadu untuk setiap algoritma. Setiap irisan dan warna peta menunjukkan nomor klaster yang sama. Keterangan tiap klaster memuat profil kerawanan dari centroid, jumlah kelurahan, dan persentasenya. Semua informasi berasal dari label hasil model yang sedang dipilih. Pada data bawaan, AHC memiliki tiga klaster: klaster 1 Dominan Bahaya Gas, 1 kelurahan (0,4%); klaster 2 Risiko Rendah, 128 kelurahan (47,9%); klaster 3 Risiko Rendah, 138 kelurahan (51,7%). Dua klaster dapat memiliki profil yang sama dan tetap ditampilkan terpisah. K-Means dan Spectral Bridges memakai format ringkasan yang sama dengan jumlah klaster masing-masing. Filter mengubah kelurahan yang ditampilkan dan penyebut persentase; jumlah klaster model tetap mengikuti hasil evaluasi. Profil centroid, evaluasi, dan analisis data tetap dapat dibuka melalui tab rincian."),
    ("Bagaimana membaca profil listrik dan gas?", "Indeks listrik adalah rata-rata centroid Z-score empat indikator kelistrikan. Indeks gas adalah rata-rata centroid lima indikator gas. Jika hanya indeks listrik >0, profilnya Dominan Bahaya Kelistrikan; jika hanya gas >0, Dominan Bahaya Gas. Jika keduanya >0, Dominan Bahaya Keduanya. Jika keduanya ≤0, labelnya Risiko Rendah. Semua anggota satu klaster memiliki indeks interpretasi klaster yang sama."),
    ("Mengapa Klaster 2 dan 3 AHC sama-sama berkategori Risiko Rendah?", "Pada data bawaan, indeks listrik dan gas Klaster 2 adalah 0,338 dan 0,434, sedangkan Klaster 3 −0,306 dan −0,449. Keduanya memenuhi aturan kedua indeks ≤0, sehingga kategori risikonya sama. Karakteristiknya berbeda: sembilan centroid indikator Klaster 2 berada di atas rata-rata tahunan (Z>0), sedangkan sembilan centroid Klaster 3 berada di bawahnya (Z<0). Ringkasan AHC kini menampilkan karakteristik ini dan kedua indeks, terpisah dari kategori risiko yang lebih umum. Buka Dasar interpretasi AHC untuk memeriksa sembilan centroid dan jumlah anggota model. Kategori memakai rata-rata indeks kelompok, sehingga satu indikator di atas 0 tidak otomatis mengubah kategorinya. Label maupun anggota klaster tidak diubah untuk membuat kategori berbeda."),
    ("Apakah label Risiko Rendah menjamin tidak terjadi kebakaran?", "Label tersebut berarti kedua indeks centroid klaster berada pada atau di bawah ambang 0 relatif terhadap dataset. Aplikasi mengelompokkan indikator kerawanan, bukan memprediksi kejadian atau menjamin keselamatan. Pencegahan dan pemeriksaan kondisi aktual tetap diperlukan."),
    ("Apa arti Silhouette, DBI, dan CHI?", "Silhouette Score mengukur pemisahan dan kekompakan klaster: lebih tinggi lebih baik, dengan rentang −1 sampai 1. Davies–Bouldin Index (DBI) lebih baik jika lebih rendah. Calinski–Harabasz Index (CHI) lebih baik jika lebih tinggi. Ketiganya mengukur struktur klaster pada data, bukan persentase akurasi."),
    ("Bagaimana sistem memilih jumlah klaster optimal?", "Sistem menguji K=2 sampai 10 dan menghitung tiga metrik. K yang didukung minimal dua metrik dipilih. Jika ketiga metrik memilih K berbeda, dipilih rata-rata peringkat paling baik; jika masih seri, Silhouette lebih tinggi lalu K lebih kecil menjadi pemutus. Untuk data kecil, K maksimal n−1."),
    ("Mengapa satu algoritma ditampilkan terlebih dahulu?", "Setelah K optimal dipilih pada masing-masing algoritma, sistem membandingkan peringkat ketiga metrik final. Algoritma dengan rata-rata peringkat terendah tampil dahulu. Jika seri, sistem memakai Silhouette lebih tinggi, lalu nama algoritma. Dua algoritma lain tetap dapat dilihat melalui tab."),
    ("Apakah kepadatan penduduk memengaruhi pembentukan klaster?", "Kepadatan penduduk, nama wilayah, tahun, latitude, longitude, dan elevasi tidak masuk model. Hanya sembilan indikator persentase yang distandardisasi dipakai sebagai masukan. Kepadatan membantu pengguna memahami konteks wilayah pada hasil. Nilai kepadatan dan koordinat profil merupakan rata-rata periode yang tersedia."),
    ("Bisakah saya mengubah parameter algoritma?", "Parameter penelitian dan pemilihan K dikendalikan sistem. K-Means menggunakan random_state=11 dan n_init=10; AHC memakai Ward; Spectral Bridges memakai random_state=549, n_nodes=15, dan p=2. Filter wilayah, pencarian, dan pilihan tampilan hanya membantu penelusuran hasil."),
    ("Apa yang terjadi setelah saya mengunggah CSV?", "Sistem memeriksa kolom, angka, persentase, koordinat, dan baris duplikat. Jika valid, data langsung menjadi sumber aktif Beranda dan Klasterisasi. Jika tidak valid, muncul penjelasan dan dataset sebelumnya tetap aktif. Data berlaku selama sesi; sesi baru kembali ke dataset bawaan."),
    ("Bagaimana membaca lapisan peta dan melihat pulau?", "Peta memakai latar geografis CARTO Voyager/OpenStreetMap serta batas administrasi dari DPMPTSP DKI Jakarta. Garis tebal menunjukkan provinsi/kota, garis tipis kecamatan, dan titik berwarna menunjukkan profil kerawanan kelurahan. Di Klasterisasi, aktifkan Batas kelurahan untuk detail tambahan. Data Kepulauan Seribu tetap ada; gunakan filter Wilayah administrasi untuk menelusurinya, atau geser dan perkecil peta. Batas tersimpan lokal; latar geografis memerlukan internet."),
    ("Bagaimana memakai saran pencarian wilayah?", "Ketik sebagian nama pada Cari kelurahan / kecamatan. Daftar disaring tanpa membedakan huruf besar dan kecil, menggunakan wilayah pada dataset aktif. Pilih dengan klik atau tombol panah dan Enter. Anda juga dapat mengetik kata lalu menekan Enter untuk mencari semua nama yang mengandung kata itu. Hapus pilihan untuk mengembalikan semua wilayah. Filter kota, tahun, dan profil yang aktif tetap berlaku."),
    ("Apa yang tersedia di tab Analisis data?", "Pilih Korelasi untuk hubungan linear antarindikator; Distribusi untuk histogram, boxplot, statistik, dan kandidat pencilan; Antar klaster untuk perbandingan indikator dan rata-rata; Jumlah & pemisahan untuk ukuran klaster dan proyeksi PCA. Persentase asli dirata-ratakan antarperiode per kelurahan. PCA memakai sembilan Z-score masukan model. Semua grafik memakai hasil algoritma yang sedang dipilih, mencakup seluruh dataset aktif, dapat diunduh sebagai PNG, dan tidak melatih ulang klaster saat pilihan grafik berubah."),
    ("Apa yang tersedia dalam laporan unduhan?", "Laporan ZIP memuat CSV hasil tiap kelurahan, profil centroid klaster, kandidat K dan metriknya untuk seluruh metode yang berhasil, tabel perbandingan metode, data agregasi, Z-score agregasi, serta catatan metodologi. Unduhan hasil tampilan hanya memuat kelurahan sesuai filter aktif."),
]

for i, (question, answer) in enumerate(questions):
    with st.expander(question, expanded=i == 0):
        st.markdown(answer)
